import { View, Text, Pressable, Animated, StyleSheet } from "react-native";
import { useRef } from "react";
import { registerRootComponent } from "expo";

function App() {
  const w = useRef(new Animated.Value(0)).current;
  const load = () => {
    Animated.timing(w, { toValue: 220, duration: 600 }).start();
  };
  return (
    <View style={styles.s}>
      <View style={styles.track}>
        <Animated.View nativeID="bar" style={[styles.fill, { width: w }]} />
      </View>
      <Pressable nativeID="load" style={styles.b} onPress={load}><Text style={styles.t}>Ачаалах</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 20, padding: 24, alignItems: "center", justifyContent: "center" },
  track: { width: 220, height: 16, backgroundColor: "#e2e8f0", borderRadius: 999, overflow: "hidden" },
